diff --git a/tests/transfer_test.go b/tests/transfer_test.go
new file mode 100644
index 0000000..ae7111f
--- /dev/null
+++ b/tests/transfer_test.go
@@ -0,0 +1,88 @@
+package tests
+
+import (
+	"errors"
+	"reflect"
+	"testing"
+
+	"example.com/bank/account"
+	"example.com/bank/ledger"
+)
+
+func newTransferLedger(t *testing.T) (*ledger.Ledger, *account.Account, *account.Account) {
+	t.Helper()
+	l := ledger.New()
+	a := account.New("a", "al", 1000)
+	a.OverdraftLimit = 100
+	b := account.New("b", "bo", 50)
+	if err := l.Open(a); err != nil {
+		t.Fatal(err)
+	}
+	if err := l.Open(b); err != nil {
+		t.Fatal(err)
+	}
+	return l, a, b
+}
+
+func TestTransferMovesMoneyAndRecordsHistory(t *testing.T) {
+	l, a, b := newTransferLedger(t)
+	if err := l.Transfer("a", "b", 300, "rent"); err != nil {
+		t.Fatal(err)
+	}
+	if a.Balance != 700 || b.Balance != 350 {
+		t.Fatalf("balances = %d, %d; want 700, 350", a.Balance, b.Balance)
+	}
+	if l.Total() != 1050 {
+		t.Fatalf("Total = %d, want 1050", l.Total())
+	}
+	wantA := []account.Entry{{Kind: "transfer-out", Amount: -300, Memo: "rent", BalanceAfter: 700, Counterparty: "b"}}
+	wantB := []account.Entry{{Kind: "transfer-in", Amount: 300, Memo: "rent", BalanceAfter: 350, Counterparty: "a"}}
+	if !reflect.DeepEqual(a.History, wantA) {
+		t.Fatalf("a.History = %+v, want %+v", a.History, wantA)
+	}
+	if !reflect.DeepEqual(b.History, wantB) {
+		t.Fatalf("b.History = %+v, want %+v", b.History, wantB)
+	}
+}
+
+func TestTransferAllowsExactOverdraftFloor(t *testing.T) {
+	l, a, _ := newTransferLedger(t)
+	if err := l.Transfer("a", "b", 1100, ""); err != nil {
+		t.Fatalf("transfer to -100 with a 100 limit: %v", err)
+	}
+	if a.Balance != -100 {
+		t.Fatalf("Balance = %d, want -100", a.Balance)
+	}
+}
+
+func TestTransferErrorsAreAtomic(t *testing.T) {
+	cases := []struct {
+		name     string
+		from, to string
+		cents    int64
+		want     error
+	}{
+		{"zero amount", "a", "b", 0, ledger.ErrInvalidAmount},
+		{"negative amount", "a", "b", -5, ledger.ErrInvalidAmount},
+		{"same account", "a", "a", 10, ledger.ErrSameAccount},
+		{"same unknown account", "zz", "zz", 10, ledger.ErrSameAccount},
+		{"unknown source", "zz", "b", 10, ledger.ErrUnknownAccount},
+		{"unknown destination", "a", "zz", 10, ledger.ErrUnknownAccount},
+		{"insufficient funds", "a", "b", 1101, ledger.ErrInsufficientFunds},
+	}
+	for _, tc := range cases {
+		t.Run(tc.name, func(t *testing.T) {
+			l, a, b := newTransferLedger(t)
+			err := l.Transfer(tc.from, tc.to, tc.cents, "x")
+			if !errors.Is(err, tc.want) {
+				t.Fatalf("err = %v, want %v", err, tc.want)
+			}
+			if a.Balance != 1000 || b.Balance != 50 {
+				t.Fatalf("balances changed: %d, %d", a.Balance, b.Balance)
+			}
+			if len(a.History) != 0 || len(b.History) != 0 {
+				t.Fatalf("history changed: %+v / %+v", a.History, b.History)
+			}
+		})
+	}
+}

diff --git a/tests/bucket_test.go b/tests/bucket_test.go
new file mode 100644
index 0000000..9f3e129
--- /dev/null
+++ b/tests/bucket_test.go
@@ -0,0 +1,96 @@
+package tests
+
+import (
+	"errors"
+	"math"
+	"testing"
+	"time"
+
+	"example.com/ratelimit/ratelimit"
+)
+
+func TestBucketRejectsBadConfig(t *testing.T) {
+	c := newClock()
+	bad := []struct {
+		capacity, refill float64
+		now              func() time.Time
+	}{
+		{0, 1, c.Now},
+		{-1, 1, c.Now},
+		{math.NaN(), 1, c.Now},
+		{math.Inf(1), 1, c.Now},
+		{1, 0, c.Now},
+		{1, math.NaN(), c.Now},
+		{1, math.Inf(1), c.Now},
+		{1, 1, nil},
+	}
+	for i, tc := range bad {
+		if _, err := ratelimit.NewBucket(tc.capacity, tc.refill, tc.now); !errors.Is(err, ratelimit.ErrInvalidConfig) {
+			t.Fatalf("case %d: err = %v, want ErrInvalidConfig", i, err)
+		}
+	}
+}
+
+func TestBucketStartsFullAndRefillsFractionally(t *testing.T) {
+	c := newClock()
+	b, err := ratelimit.NewBucket(4, 2, c.Now)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if !b.Allow(4) {
+		t.Fatal("a new bucket should allow its full capacity")
+	}
+	if b.Allow(1) {
+		t.Fatal("an empty bucket should refuse")
+	}
+	c.Advance(250 * time.Millisecond)
+	if got := b.Tokens(); got != 0.5 {
+		t.Fatalf("Tokens = %v, want 0.5", got)
+	}
+}
+
+func TestBucketNoPartialConsumption(t *testing.T) {
+	c := newClock()
+	b, _ := ratelimit.NewBucket(3, 1, c.Now)
+	if b.Allow(4) {
+		t.Fatal("n greater than capacity must be refused")
+	}
+	if !b.Allow(2) {
+		t.Fatal("2 of 3 tokens should be allowed")
+	}
+	if b.Allow(2) {
+		t.Fatal("only 1 token left, 2 must be refused")
+	}
+	if got := b.Tokens(); got != 1 {
+		t.Fatalf("Tokens = %v, want 1 (refused Allow must take nothing)", got)
+	}
+	for _, n := range []float64{0, -1, math.NaN()} {
+		if b.Allow(n) {
+			t.Fatalf("Allow(%v) must be refused", n)
+		}
+	}
+}
+
+func TestBucketCapsAtCapacity(t *testing.T) {
+	c := newClock()
+	b, _ := ratelimit.NewBucket(2, 10, c.Now)
+	b.Allow(2)
+	c.Advance(time.Hour)
+	if got := b.Tokens(); got != 2 {
+		t.Fatalf("Tokens = %v, want capacity 2", got)
+	}
+}
+
+func TestBucketClockGoingBackwards(t *testing.T) {
+	c := newClock()
+	b, _ := ratelimit.NewBucket(10, 1, c.Now)
+	b.Allow(10)
+	c.Advance(-time.Second)
+	if got := b.Tokens(); got != 0 {
+		t.Fatalf("Tokens after clock went back = %v, want 0", got)
+	}
+	c.Advance(2 * time.Second) // 1s past the latest time seen
+	if got := b.Tokens(); got != 1 {
+		t.Fatalf("Tokens = %v, want 1 once the clock passes the reference time", got)
+	}
+}

diff --git a/sched/plan_test.go b/sched/plan_test.go
new file mode 100644
index 0000000..f4c7860
--- /dev/null
+++ b/sched/plan_test.go
@@ -0,0 +1,162 @@
+package sched
+
+import (
+	"errors"
+	"fmt"
+	"reflect"
+	"strconv"
+	"testing"
+	"time"
+)
+
+func TestPlanBatches(t *testing.T) {
+	got, err := Plan(map[string][]string{
+		"app":  {"lib", "util", "lib"},
+		"lib":  {"util"},
+		"util": nil,
+		"zed":  {},
+	})
+	if err != nil {
+		t.Fatal(err)
+	}
+	want := [][]string{{"util", "zed"}, {"lib"}, {"app"}}
+	if !reflect.DeepEqual(got, want) {
+		t.Fatalf("Plan = %v, want %v", got, want)
+	}
+}
+
+func TestPlanEmpty(t *testing.T) {
+	got, err := Plan(nil)
+	if err != nil || got == nil || len(got) != 0 {
+		t.Fatalf("Plan(nil) = %v, %v", got, err)
+	}
+}
+
+func TestPlanUnknownBeforeCycle(t *testing.T) {
+	_, err := Plan(map[string][]string{
+		"a": {"b"}, "b": {"a"}, "c": {"x", "w"}, "d": {"zz"},
+	})
+	var ue *UnknownDepError
+	if !errors.As(err, &ue) || ue.Task != "c" || ue.Dep != "w" {
+		t.Fatalf("err = %v", err)
+	}
+	if ue.Error() != `task "c" depends on unknown task "w"` {
+		t.Fatalf("Error() = %q", ue.Error())
+	}
+}
+
+func TestCycleCanonicalPath(t *testing.T) {
+	_, err := Plan(map[string][]string{
+		"p": {"r", "q"}, "q": {"s"}, "s": {"p"}, "r": {"p"},
+	})
+	var ce *CycleError
+	if !errors.As(err, &ce) {
+		t.Fatalf("err = %v", err)
+	}
+	if want := []string{"p", "q", "s", "p"}; !reflect.DeepEqual(ce.Path, want) {
+		t.Fatalf("Path = %v, want %v", ce.Path, want)
+	}
+	_, err = Plan(map[string][]string{"b": {"b"}})
+	if err == nil || err.Error() != "dependency cycle: b -> b" {
+		t.Fatalf("self-loop err = %v", err)
+	}
+}
+
+func TestSimulateBasic(t *testing.T) {
+	s, err := Simulate(map[string]Task{
+		"a": {Duration: 3},
+		"b": {Duration: 2, Deps: []string{"a"}},
+		"c": {Duration: 5},
+		"d": {Duration: 1, Deps: []string{"b", "c"}},
+	}, 2)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if s.Makespan != 6 {
+		t.Fatalf("Makespan = %d", s.Makespan)
+	}
+	if want := []string{"a", "b", "d"}; !reflect.DeepEqual(s.CriticalPath, want) {
+		t.Fatalf("CriticalPath = %v", s.CriticalPath)
+	}
+	if got := s.Slots["c"]; got != (Slot{Start: 0, End: 5, Worker: 0}) {
+		t.Fatalf("c slot = %+v", got)
+	}
+	if got := s.Slots["a"]; got != (Slot{Start: 0, End: 3, Worker: 1}) {
+		t.Fatalf("a slot = %+v", got)
+	}
+}
+
+func TestSimulateErrors(t *testing.T) {
+	if _, err := Simulate(map[string]Task{"a": {Duration: 1}}, 0); !errors.Is(err, ErrNoWorkers) {
+		t.Fatalf("workers err = %v", err)
+	}
+	_, err := Simulate(map[string]Task{"b": {Duration: 0}, "a": {Duration: -1}}, 1)
+	var de *InvalidDurationError
+	if !errors.As(err, &de) || de.Task != "a" {
+		t.Fatalf("duration err = %v", err)
+	}
+	s, err := Simulate(nil, 1)
+	if err != nil || s.Slots == nil || s.Makespan != 0 || s.CriticalPath == nil {
+		t.Fatalf("empty = %+v, %v", s, err)
+	}
+}
+
+func TestScaleLargeGraphs(t *testing.T) {
+	const n = 200000
+	// Chain of 100000 tasks plus wide fan-in tasks with up to 5 deps.
+	tasks := make(map[string][]string, n)
+	for i := 0; i < n; i++ {
+		name := "t" + strconv.Itoa(i)
+		var deps []string
+		if i > 0 {
+			deps = append(deps, "t"+strconv.Itoa(i-1))
+		}
+		for k := 1; k <= 4 && i-k*1000 >= 0; k++ {
+			deps = append(deps, "t"+strconv.Itoa(i-k*1000))
+		}
+		tasks[name] = deps
+	}
+	start := time.Now()
+	if _, err := Plan(tasks); err != nil {
+		t.Fatal(err)
+	}
+	if d := time.Since(start); d > 2*time.Second {
+		t.Fatalf("Plan took %v", d)
+	}
+
+	stasks := make(map[string]Task, n)
+	for name, deps := range tasks {
+		stasks[name] = Task{Deps: deps, Duration: 1 + len(name)%7, Priority: len(name) % 3}
+	}
+	start = time.Now()
+	if _, err := Simulate(stasks, 8); err != nil {
+		t.Fatal(err)
+	}
+	if d := time.Since(start); d > 2*time.Second {
+		t.Fatalf("Simulate took %v", d)
+	}
+}
+
+func TestScaleRingCycle(t *testing.T) {
+	const ring = 100000
+	tasks := make(map[string][]string, 200000)
+	for i := 0; i < 100000; i++ {
+		tasks[fmt.Sprintf("a%06d", i)] = []string{"base"}
+	}
+	tasks["base"] = nil
+	for i := 0; i < ring; i++ {
+		tasks[fmt.Sprintf("r%06d", i)] = []string{fmt.Sprintf("r%06d", (i+1)%ring)}
+	}
+	for i := 0; i < 100000-1; i++ {
+		tasks[fmt.Sprintf("c%06d", i)] = []string{fmt.Sprintf("r%06d", i%ring)}
+	}
+	start := time.Now()
+	_, err := Plan(tasks)
+	if d := time.Since(start); d > 2*time.Second {
+		t.Fatalf("Plan took %v", d)
+	}
+	var ce *CycleError
+	if !errors.As(err, &ce) || len(ce.Path) != ring+1 {
+		t.Fatalf("err = %v", err)
+	}
+}

