diff --git a/tests/loki_wall_eval.rs b/tests/loki_wall_eval.rs
new file mode 100644
index 0000000..560fb28
--- /dev/null
+++ b/tests/loki_wall_eval.rs
@@ -0,0 +1,158 @@
+use std::collections::HashMap;
+use std::time::{Duration, Instant};
+
+fn vars() -> HashMap<String, f64> {
+    let mut m = HashMap::new();
+    m.insert("x".to_string(), 3.0);
+    m.insert("y".to_string(), 4.0);
+    m
+}
+
+fn ok(s: &str) -> f64 {
+    match exprkit::eval(s, &vars()) {
+        Ok(v) => v,
+        Err(e) => panic!("{:?} gave Err({:?})", s.len(), e),
+    }
+}
+
+fn ok_timed(s: &str) -> f64 {
+    let start = Instant::now();
+    let v = ok(s);
+    assert!(start.elapsed() < Duration::from_secs(2), "too slow: {:?}", start.elapsed());
+    v
+}
+
+fn er(s: &str) -> String {
+    match exprkit::eval(s, &vars()) {
+        Ok(v) => panic!("{:?} gave Ok({:?})", s, v),
+        Err(e) => format!("{:?}", e),
+    }
+}
+
+#[test]
+fn numbers_and_identifiers() {
+    assert_eq!(ok("3"), 3.0);
+    assert_eq!(ok("007"), 7.0);
+    assert_eq!(ok("0.5"), 0.5);
+    assert_eq!(ok("10.25"), 10.25);
+    assert_eq!(er(".5"), "Parse { pos: 0 }");
+    assert_eq!(er("5."), "Parse { pos: 1 }");
+    assert_eq!(er("X"), "Parse { pos: 0 }");
+    assert_eq!(er("x3"), "UnknownVar(\"x3\")");
+    assert_eq!(ok("x"), 3.0);
+}
+
+#[test]
+fn whitespace_is_ignored() {
+    assert_eq!(ok(" 1 +\t2\n"), 3.0);
+    assert_eq!(ok("1\r\n+ 2"), 3.0);
+    assert_eq!(er("1\t2"), "Parse { pos: 2 }");
+}
+
+#[test]
+fn operators_and_precedence() {
+    assert_eq!(ok("-2^2"), -4.0);
+    assert_eq!(ok("(-2)^2"), 4.0);
+    assert_eq!(ok("2^-1"), 0.5);
+    assert_eq!(ok("2^3^2"), 512.0);
+    assert_eq!(ok("--3"), 3.0);
+    assert_eq!(ok("2--2"), 4.0);
+    assert_eq!(ok("7 % 4 % 2"), 1.0);
+    assert_eq!(ok("-7 % 3"), -1.0);
+    assert_eq!(ok("7.5 % 2"), 1.5);
+    assert_eq!(ok("8 / 2 / 2"), 2.0);
+    assert_eq!(er("8 / 2 / 0"), "DivByZero");
+    assert_eq!(er("1 % 0"), "DivByZero");
+    assert_eq!(er("1 / -0"), "DivByZero");
+}
+
+#[test]
+fn implicit_multiplication() {
+    assert_eq!(ok("2x"), 6.0);
+    assert_eq!(ok("2 x"), 6.0);
+    assert_eq!(ok("x y"), 12.0);
+    assert_eq!(ok("2(3+4)"), 14.0);
+    assert_eq!(ok("(1+2)(3+4)"), 21.0);
+    assert_eq!(ok("2(3)(4)"), 24.0);
+    assert_eq!(ok("3abs(-2)"), 6.0);
+    assert_eq!(ok("2x^2"), 18.0);
+    assert_eq!(ok("-2x"), -6.0);
+    assert_eq!(ok("2^3x"), 24.0);
+    assert_eq!(ok("6/2(1+2)"), 9.0);
+    assert_eq!(er("2x(3)"), "UnknownFunc(\"x\")");
+    assert_eq!(er("2 3"), "Parse { pos: 2 }");
+    assert_eq!(er("(2)3"), "Parse { pos: 3 }");
+    assert_eq!(er("x 2"), "Parse { pos: 2 }");
+}
+
+#[test]
+fn parse_error_positions() {
+    assert_eq!(er("1 + 2)"), "Parse { pos: 5 }");
+    assert_eq!(er("()"), "Parse { pos: 1 }");
+    assert_eq!(er("1,2"), "Parse { pos: 1 }");
+    assert_eq!(er("min(1 2)"), "Parse { pos: 6 }");
+    assert_eq!(er("min(,1)"), "Parse { pos: 4 }");
+    assert_eq!(er("min(1,)"), "Parse { pos: 6 }");
+    assert_eq!(er(""), "Parse { pos: 0 }");
+    assert_eq!(er("   "), "Parse { pos: 3 }");
+    assert_eq!(er("(1 + 2"), "Parse { pos: 6 }");
+    assert_eq!(er("1 +"), "Parse { pos: 3 }");
+    assert_eq!(er("max(1"), "Parse { pos: 5 }");
+    assert_eq!(er("zz + 1 2"), "Parse { pos: 7 }");
+}
+
+#[test]
+fn functions() {
+    assert_eq!(ok("min(3,1,2)"), 1.0);
+    assert_eq!(ok("max(3,1,2)"), 3.0);
+    assert_eq!(ok("abs(-2)"), 2.0);
+    assert_eq!(ok("sqrt(16)"), 4.0);
+    assert_eq!(er("sqrt(-1)"), "Domain(\"sqrt\")");
+    assert_eq!(er("foo(1)"), "UnknownFunc(\"foo\")");
+    assert_eq!(er("x(1)"), "UnknownFunc(\"x\")");
+    assert_eq!(er("min()"), "Arity { name: \"min\", expected: \"at least 1\", got: 0 }");
+    assert_eq!(er("abs(1,2)"), "Arity { name: \"abs\", expected: \"1\", got: 2 }");
+    assert_eq!(er("sqrt()"), "Arity { name: \"sqrt\", expected: \"1\", got: 0 }");
+}
+
+#[test]
+fn evaluation_order_and_errors() {
+    assert_eq!(er("q + w"), "UnknownVar(\"q\")");
+    assert_eq!(er("zz / (1/0)"), "UnknownVar(\"zz\")");
+    assert_eq!(er("1/0 + q"), "DivByZero");
+    assert_eq!(er("min(q, zz)"), "UnknownVar(\"q\")");
+    assert_eq!(er("sqrt(q)"), "UnknownVar(\"q\")");
+    assert_eq!(er("foo(q)"), "UnknownFunc(\"foo\")");
+    assert_eq!(er("abs(y, q)"), "Arity { name: \"abs\", expected: \"1\", got: 2 }");
+    assert_eq!(er("1 + 2 )"), "Parse { pos: 6 }");
+}
+
+#[test]
+fn deep_and_long_inputs() {
+    let n = 100000;
+
+    let parens = format!("{}1{}", "(".repeat(n), ")".repeat(n));
+    assert_eq!(ok_timed(&parens), 1.0);
+    let unbalanced = format!("{}1{}", "(".repeat(n), ")".repeat(n - 1));
+    assert_eq!(er(&unbalanced), "Parse { pos: 200000 }");
+
+    let abs_chain = format!("{}-3{}", "abs(".repeat(n), ")".repeat(n));
+    assert_eq!(ok_timed(&abs_chain), 3.0);
+
+    let max_chain = format!("{}5{}", "max(1, ".repeat(n), ")".repeat(n));
+    assert_eq!(ok_timed(&max_chain), 5.0);
+
+    let even_minus = format!("{}1", "-".repeat(n));
+    assert_eq!(ok_timed(&even_minus), 1.0);
+    let odd_minus = format!("{}1", "-".repeat(n - 1));
+    assert_eq!(ok_timed(&odd_minus), -1.0);
+
+    let pow_chain = format!("{}1", "1^".repeat(n));
+    assert_eq!(ok_timed(&pow_chain), 1.0);
+
+    let sum = format!("{}1", "1+".repeat(2 * n - 1));
+    assert_eq!(ok_timed(&sum), 200000.0);
+
+    let repeated = "(1)".repeat(n);
+    assert_eq!(ok_timed(&repeated), 1.0);
+}

diff --git a/tests/interval_set_spec.rs b/tests/interval_set_spec.rs
new file mode 100644
index 0000000..ab9590b
--- /dev/null
+++ b/tests/interval_set_spec.rs
@@ -0,0 +1,103 @@
+use intervalkit::{Bound, IntervalSet};
+use std::time::Instant;
+
+use Bound::{Closed as C, Open as O};
+
+#[test]
+fn empty_forms_and_point_merging() {
+    let mut s = IntervalSet::new();
+    s.insert(C(2), C(2));
+    s.insert(O(2), O(2));
+    s.insert(C(2), O(2));
+    s.insert(O(2), C(2));
+    s.insert(C(3), C(2));
+    assert_eq!(s.ranges(), vec![(C(2), C(2))]);
+    assert_eq!(s.to_string(), "{[2,2]}");
+
+    let mut m = IntervalSet::new();
+    m.insert(C(1), O(3));
+    m.insert(C(3), C(5));
+    assert_eq!(m.ranges(), vec![(C(1), C(5))]);
+
+    let mut n = IntervalSet::new();
+    n.insert(O(1), O(3));
+    n.insert(C(3), C(3));
+    assert_eq!(n.ranges(), vec![(O(1), C(3))]);
+
+    let mut k = IntervalSet::new();
+    k.insert(O(1), O(3));
+    k.insert(O(3), O(5));
+    assert_eq!(k.ranges(), vec![(O(1), O(3)), (O(3), O(5))]);
+    assert_eq!(k.to_string(), "{(1,3), (3,5)}");
+}
+
+#[test]
+fn remove_splits_intervals() {
+    let mut s = IntervalSet::new();
+    s.insert(C(1), C(5));
+    s.remove(C(2), C(2));
+    assert_eq!(s.ranges(), vec![(C(1), O(2)), (O(2), C(5))]);
+
+    let mut t = IntervalSet::new();
+    t.insert(C(1), C(5));
+    t.remove(O(2), O(4));
+    assert_eq!(t.ranges(), vec![(C(1), C(2)), (C(4), C(5))]);
+    assert_eq!(t.to_string(), "{[1,2], [4,5]}");
+}
+
+#[test]
+fn measure_complement_and_display() {
+    let mut s = IntervalSet::new();
+    s.insert(C(2), O(4));
+    s.insert(O(6), C(8));
+    assert_eq!(
+        s.complement(C(0), C(10)),
+        vec![(C(0), O(2)), (C(4), C(6)), (O(8), C(10))]
+    );
+    assert_eq!(s.measure(), 4);
+    assert!(s.complement(C(3), O(3)).is_empty());
+    assert_eq!(IntervalSet::new().to_string(), "{}");
+
+    let mut e = IntervalSet::new();
+    e.insert(O(-3), C(0));
+    assert_eq!(e.to_string(), "{(-3,0]}");
+}
+
+#[test]
+fn extreme_endpoints() {
+    let mut s = IntervalSet::new();
+    s.insert(C(i64::MIN), C(i64::MAX));
+    assert_eq!(s.measure(), (i64::MAX as i128) - (i64::MIN as i128));
+    assert!(s.contains(0.0));
+    s.remove(C(i64::MIN), O(i64::MAX));
+    assert_eq!(s.ranges(), vec![(C(i64::MAX), C(i64::MAX))]);
+}
+
+#[test]
+fn large_descending_workload_is_fast() {
+    let mut s = IntervalSet::new();
+    let mut seed: u64 = 0x9E37_79B9_7F4A_7C15;
+    let mut next = move || {
+        seed ^= seed << 13;
+        seed ^= seed >> 7;
+        seed ^= seed << 17;
+        seed
+    };
+    let start = Instant::now();
+    let mut pos: i64 = 1_000_000_000;
+    for _ in 0..300_000 {
+        let len = (next() % 1001) as i64;
+        let jitter = (next() % 7) as i64;
+        pos -= 1 + jitter;
+        let lo = pos.max(0);
+        let hi = lo + len;
+        if next() % 2 == 0 {
+            s.insert(C(lo), C(hi));
+        } else {
+            s.remove(C(lo), O(hi));
+        }
+        let x = (next() % 1_000_000_001) as f64;
+        let _ = s.contains(x);
+    }
+    assert!(start.elapsed().as_secs_f64() < 3.0);
+}

diff --git a/tests/loki_wall_roman.rs b/tests/loki_wall_roman.rs
new file mode 100644
index 0000000..5deec26
--- /dev/null
+++ b/tests/loki_wall_roman.rs
@@ -0,0 +1,97 @@
+use romankit::roman::{from_roman, to_roman, RomanError};
+use std::collections::HashSet;
+
+fn canonical_set() -> HashSet<String> {
+    (1..=3999u32).map(|n| to_roman(n).unwrap()).collect()
+}
+
+#[test]
+fn to_roman_rejects_out_of_range() {
+    assert!(matches!(to_roman(0), Err(RomanError::OutOfRange)));
+    assert!(matches!(to_roman(4000), Err(RomanError::OutOfRange)));
+    assert!(matches!(to_roman(u32::MAX), Err(RomanError::OutOfRange)));
+    assert_ne!(to_roman(0).ok().as_deref(), Some(""));
+    assert_ne!(to_roman(4000).ok().as_deref(), Some("MMMM"));
+}
+
+#[test]
+fn to_roman_gives_canonical_numerals_in_range() {
+    assert_eq!(to_roman(1).unwrap(), "I");
+    assert_eq!(to_roman(4).unwrap(), "IV");
+    assert_eq!(to_roman(19).unwrap(), "XIX");
+    assert_eq!(to_roman(1994).unwrap(), "MCMXCIV");
+    assert_eq!(to_roman(3999).unwrap(), "MMMCMXCIX");
+    assert_ne!(to_roman(4).unwrap(), "IIII");
+}
+
+#[test]
+fn from_roman_parses_subtractive_endings() {
+    assert_eq!(from_roman("IV"), Ok(4));
+    assert_eq!(from_roman("XIX"), Ok(19));
+    assert_eq!(from_roman("MCMXCIV"), Ok(1994));
+    assert_ne!(from_roman("IV"), Ok(6));
+    assert_ne!(from_roman("XIX"), Ok(21));
+}
+
+#[test]
+fn from_roman_rejects_non_canonical_forms() {
+    for s in ["IIII", "IC", "VX", "MMMM", "IIV", "XM"] {
+        assert!(matches!(from_roman(s), Err(RomanError::NonCanonical)), "{s}");
+    }
+    assert!(from_roman("IIII").is_err());
+}
+
+#[test]
+fn from_roman_rejects_empty_string() {
+    assert!(matches!(from_roman(""), Err(RomanError::Empty)));
+    assert!(from_roman("").is_err());
+}
+
+#[test]
+fn from_roman_reports_first_invalid_char() {
+    assert!(matches!(from_roman("xiv"), Err(RomanError::InvalidChar('x'))));
+    assert!(matches!(from_roman("I V"), Err(RomanError::InvalidChar(' '))));
+    assert!(matches!(from_roman("IQxI"), Err(RomanError::InvalidChar('Q'))));
+    assert!(matches!(from_roman("xIIII"), Err(RomanError::InvalidChar('x'))));
+}
+
+#[test]
+fn from_roman_never_returns_out_of_range() {
+    for s in ["MMMM", "MMMMM", "IIII", "", "xiv", "IC"] {
+        assert!(!matches!(from_roman(s), Err(RomanError::OutOfRange)), "{s}");
+    }
+}
+
+#[test]
+fn round_trip_is_exact_for_whole_range() {
+    for n in 1..=3999u32 {
+        let s = to_roman(n).unwrap();
+        assert_eq!(from_roman(&s), Ok(n), "{s}");
+    }
+}
+
+#[test]
+fn from_roman_ok_iff_to_roman_matches_exhaustively() {
+    let canon = canonical_set();
+    let alphabet: Vec<char> = "IVXLCDM".chars().collect();
+    let mut candidates: Vec<String> = vec![String::new()];
+    for len in 1..=4 {
+        let mut next = Vec::new();
+        for prefix in candidates.iter().filter(|c| c.len() == len - 1) {
+            for &ch in &alphabet {
+                next.push(format!("{prefix}{ch}"));
+            }
+        }
+        candidates.extend(next);
+    }
+    for s in candidates.iter().filter(|c| !c.is_empty()) {
+        match from_roman(s) {
+            Ok(n) => {
+                assert!(canon.contains(s), "accepted non-canonical {s}");
+                assert_eq!(to_roman(n).unwrap(), *s);
+            }
+            Err(RomanError::NonCanonical) => assert!(!canon.contains(s), "rejected canonical {s}"),
+            Err(e) => panic!("unexpected error for {s}: {e:?}"),
+        }
+    }
+}

