+use shapekit::area::area;
+use shapekit::perimeter::perimeter;
+use shapekit::{Shape, ShapeError};
+use std::f64::consts::PI;
+
+fn close(actual: f64, expected: f64) -> bool {
+    (actual - expected).abs() < 1e-9
+}
+
+#[test]
+fn parse_kind_is_ascii_case_insensitive() {
+    assert_eq!(Shape::parse("CIRCLE", &[1.5]), Ok(Shape::Circle { r: 1.5 }));
+    assert_eq!(Shape::parse("Triangle", &[3.0, 4.0, 5.0]), Ok(Shape::Triangle { a: 3.0, b: 4.0, c: 5.0 }));
+    assert_ne!(Shape::parse("circle", &[1.0]), Err(ShapeError::UnknownKind("circle".to_string())));
+}
+
+#[test]
+fn parse_rect_rectangle_and_square_map_to_rect() {
+    assert_eq!(Shape::parse("rect", &[2.0, 3.0]), Ok(Shape::Rect { w: 2.0, h: 3.0 }));
+    assert_eq!(Shape::parse("RECTANGLE", &[2.0, 3.0]), Ok(Shape::Rect { w: 2.0, h: 3.0 }));
+    assert_eq!(Shape::parse("Square", &[4.0]), Ok(Shape::Rect { w: 4.0, h: 4.0 }));
+    assert_eq!(Shape::parse("square", &[]), Err(ShapeError::WrongParamCount { expected: 1, got: 0 }));
+}
+
+#[test]
+fn parse_unknown_kind_keeps_caller_spelling_in_message() {
+    let err = Shape::parse("HeXagon", &[1.0]).unwrap_err();
+    assert_eq!(err, ShapeError::UnknownKind("HeXagon".to_string()));
+    assert_eq!(err.to_string(), "unknown shape kind: HeXagon");
+    assert!(Shape::parse("hexagon", &[1.0]).is_err());
+}
+
+#[test]
+fn parse_wrong_param_count_reports_expected_and_got() {
+    let err = Shape::parse("rect", &[1.0, 2.0, 3.0]).unwrap_err();
+    assert_eq!(err, ShapeError::WrongParamCount { expected: 2, got: 3 });
+    assert_eq!(err.to_string(), "expected 2 params, got 3");
+    assert!(Shape::parse("circle", &[1.0, 2.0]).is_err());
+}
+
+#[test]
+fn parse_rejects_negative_parameter() {
+    assert_eq!(Shape::parse("circle", &[-1.0]), Err(ShapeError::NegativeDimension));
+    assert_eq!(ShapeError::NegativeDimension.to_string(), "dimensions must be non-negative");
+    assert!(Shape::parse("rect", &[1.0, -2.0]).is_err());
+}
+
+#[test]
+fn parse_check_order_kind_then_count_then_negative_then_triangle() {
+    assert_eq!(
+        Shape::parse("hexagon", &[-1.0]),
+        Err(ShapeError::UnknownKind("hexagon".to_string()))
+    );
+    assert_eq!(
+        Shape::parse("circle", &[-1.0, 2.0]),
+        Err(ShapeError::WrongParamCount { expected: 1, got: 2 })
+    );
+    assert_eq!(Shape::parse("triangle", &[-1.0, 1.0, 1.0]), Err(ShapeError::NegativeDimension));
+}
+
+#[test]
+fn parse_triangle_inequality_is_strict_and_message_matches() {
+    let err = Shape::parse("triangle", &[1.0, 1.0, 3.0]).unwrap_err();
+    assert_eq!(err, ShapeError::InvalidTriangle);
+    assert_eq!(err.to_string(), "sides do not form a triangle");
+    assert_eq!(Shape::parse("triangle", &[1.0, 2.0, 3.0]), Ok(Shape::Triangle { a: 1.0, b: 2.0, c: 3.0 }));
+}
+
+#[test]
+fn methods_compute_area_and_perimeter() {
+    let circle = Shape::Circle { r: 2.0 };
+    assert!(close(circle.area().unwrap(), 4.0 * PI));
+    assert!(close(circle.perimeter().unwrap(), 4.0 * PI));
+    assert!(!close(circle.area().unwrap(), 0.0));
+
+    let rect = Shape::Rect { w: 3.0, h: 4.0 };
+    assert!(close(rect.area().unwrap(), 12.0));
+    assert!(close(rect.perimeter().unwrap(), 14.0));
+    assert!(!close(rect.perimeter().unwrap(), 12.0));
+
+    let tri = Shape::Triangle { a: 3.0, b: 4.0, c: 5.0 };
+    assert!(close(tri.area().unwrap(), 6.0));
+    assert!(close(tri.perimeter().unwrap(), 12.0));
+    assert!(!close(tri.area().unwrap(), 12.0));
+}
+
+#[test]
+fn methods_keep_zero_dimensions_and_degenerate_triangles_valid() {
+    assert!(close(Shape::Circle { r: 0.0 }.area().unwrap(), 0.0));
+    assert!(close(Shape::Rect { w: 0.0, h: 5.0 }.perimeter().unwrap(), 10.0));
+    let degenerate = Shape::Triangle { a: 1.0, b: 2.0, c: 3.0 };
+    assert!(close(degenerate.area().unwrap(), 0.0));
+    assert!(close(degenerate.perimeter().unwrap(), 6.0));
+    assert_eq!(Shape::Triangle { a: 1.0, b: 1.0, c: 3.0 }.area(), Err(ShapeError::InvalidTriangle));
+}
+
+#[test]
+fn methods_reject_negative_dimension_before_triangle_check() {
+    assert_eq!(Shape::Rect { w: -1.0, h: 2.0 }.area(), Err(ShapeError::NegativeDimension));
+    assert_eq!(Shape::Circle { r: -1.0 }.perimeter(), Err(ShapeError::NegativeDimension));
+    assert_eq!(Shape::Triangle { a: -5.0, b: 1.0, c: 1.0 }.area(), Err(ShapeError::NegativeDimension));
+    assert_eq!(Shape::Triangle { a: 1.0, b: 1.0, c: 3.0 }.perimeter(), Err(ShapeError::InvalidTriangle));
+}
+
+#[test]
+fn area_wrapper_matches_behaviour_and_messages() {
+    assert_eq!(area("Square", &[2.0]), Ok(4.0));
+    assert!(close(area("rect", &[3.0, 4.0]).unwrap(), 12.0));
+    assert_eq!(area("hexagon", &[1.0]), Err("unknown shape kind: hexagon".to_string()));
+    assert_eq!(area("circle", &[]), Err("expected 1 params, got 0".to_string()));
+    assert_eq!(area("triangle", &[1.0, 1.0, 3.0]), Err("sides do not form a triangle".to_string()));
+}
+
+#[test]
+fn perimeter_wrapper_matches_behaviour_and_messages() {
+    assert_eq!(perimeter("square", &[2.0]), Ok(8.0));
+    assert!(close(perimeter("triangle", &[3.0, 4.0, 5.0]).unwrap(), 12.0));
+    assert_eq!(perimeter("circle", &[-1.0]), Err("dimensions must be non-negative".to_string()));
+    assert_eq!(perimeter("hexagon", &[]), Err("unknown shape kind: hexagon".to_string()));
+}
+
+#[test]
+fn crate_root_reexports_shape_and_error() {
+    let s: shapekit::Shape = shapekit::Shape::Circle { r: 1.0 };
+    let e: shapekit::ShapeError = shapekit::ShapeError::InvalidTriangle;
+    assert_eq!(s, Shape::Circle { r: 1.0 });
+    assert_eq!(e.to_string(), "sides do not form a triangle");
+    assert_ne!(e, ShapeError::NegativeDimension);
+}

diff --git a/tests/loki_wall_stats.rs b/tests/loki_wall_stats.rs
