+use statkit::report::summary;
+use statkit::stats::{count, mean, median, percentile};
+
+fn close(a: f64, b: f64) -> bool {
+    (a - b).abs() < 1e-9
+}
+
+#[test]
+fn count_ignores_nan() {
+    assert_eq!(count(&[1.0, f64::NAN, 3.0]), 2);
+    assert_ne!(count(&[1.0, f64::NAN, 3.0]), 3);
+}
+
+#[test]
+fn count_all_nan_and_empty_are_zero() {
+    assert_eq!(count(&[f64::NAN, f64::NAN]), 0);
+    assert_eq!(count(&[]), 0);
+}
+
+#[test]
+fn mean_ignores_nan() {
+    let m = mean(&[1.0, f64::NAN, 3.0]).expect("defined over non-NaN values");
+    assert!(close(m, 2.0));
+    assert!(!m.is_nan());
+}
+
+#[test]
+fn mean_basic_value() {
+    let m = mean(&[1.0, 2.0, 3.0, 4.0]).unwrap();
+    assert!(close(m, 2.5));
+    assert!(mean(&[1.0, 2.0, 3.0, 4.0]).map_or(false, |x| !x.is_nan()));
+}
+
+#[test]
+fn mean_none_when_no_non_nan_values() {
+    assert_eq!(mean(&[]), None);
+    assert_eq!(mean(&[f64::NAN, f64::NAN]), None);
+}
+
+#[test]
+fn median_is_percentile_50_and_ignores_nan() {
+    let m = median(&[1.0, 2.0, 3.0, 4.0]).unwrap();
+    assert!(close(m, 2.5));
+    let n = median(&[1.0, f64::NAN, 3.0]).unwrap();
+    assert!(close(n, 2.0));
+    assert!(close(n, percentile(&[1.0, f64::NAN, 3.0], 50.0).unwrap()));
+}
+
+#[test]
+fn median_none_when_no_non_nan_values() {
+    assert_eq!(median(&[]), None);
+    assert_eq!(median(&[f64::NAN]), None);
+}
+
+#[test]
+fn percentile_none_when_no_non_nan_values() {
+    assert_eq!(percentile(&[], 50.0), None);
+    assert_eq!(percentile(&[f64::NAN, f64::NAN], 90.0), None);
+}
+
+#[test]
+fn percentile_none_for_nan_or_out_of_range_p() {
+    let v = [1.0, 2.0, 3.0, 4.0];
+    assert_eq!(percentile(&v, f64::NAN), None);
+    assert_eq!(percentile(&v, -0.1), None);
+    assert_eq!(percentile(&v, 100.1), None);
+    assert!(percentile(&v, 0.0).is_some());
+    assert!(percentile(&v, 100.0).is_some());
+}
+
+#[test]
+fn percentile_linear_interpolation_between_closest_ranks() {
+    let v = [1.0, 2.0, 3.0, 4.0];
+    assert!(close(percentile(&v, 50.0).unwrap(), 2.5));
+    assert!(close(percentile(&v, 90.0).unwrap(), 3.7));
+    assert!(!close(percentile(&v, 90.0).unwrap(), 3.0));
+}
+
+#[test]
+fn percentile_endpoints_are_min_and_max() {
+    let v = [4.0, 1.0, 3.0, 2.0];
+    assert!(close(percentile(&v, 0.0).unwrap(), 1.0));
+    assert!(close(percentile(&v, 100.0).unwrap(), 4.0));
+}
+
+#[test]
+fn percentile_independent_of_input_order() {
+    let a = [1.0, 2.0, 3.0, 4.0];
+    let b = [3.0, 1.0, 4.0, 2.0];
+    assert!(close(percentile(&a, 90.0).unwrap(), percentile(&b, 90.0).unwrap()));
+    assert!(close(percentile(&b, 50.0).unwrap(), 2.5));
+    assert!(!close(percentile(&b, 50.0).unwrap(), 2.0));
+}
+
+#[test]
+fn percentile_does_not_modify_input() {
+    let v = vec![3.0, 1.0, 2.0];
+    let _ = percentile(&v, 50.0);
+    assert_eq!(v, vec![3.0, 1.0, 2.0]);
+}
+
+#[test]
+fn percentile_ignores_nan_in_interpolation() {
+    let p = percentile(&[f64::NAN, 1.0, 3.0, f64::NAN], 100.0).unwrap();
+    assert!(close(p, 3.0));
+    assert!(!p.is_nan());
+}
+
+#[test]
+fn summary_reports_fixed_values() {
+    assert_eq!(summary(&[1.0, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_ne!(summary(&[1.0, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.00 p90=3.00");
+}
+
+#[test]
+fn summary_is_order_independent() {
+    assert_eq!(summary(&[4.0, 2.0, 1.0, 3.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+}
+
+#[test]
+fn summary_empty_and_all_nan_is_just_count() {
+    assert_eq!(summary(&[]), "n=0");
+    assert_eq!(summary(&[f64::NAN, f64::NAN]), "n=0");
+}
+
+#[test]
+fn summary_ignores_nan_values() {
+    assert_eq!(summary(&[1.0, f64::NAN, 3.0]), "n=2 mean=2.00 p50=2.00 p90=2.80");
+    assert!(!summary(&[1.0, f64::NAN, 3.0]).contains("NaN"));
+}
diff --git a/tests/nan_and_percentile.rs b/tests/nan_and_percentile.rs
