+func TestBucketRejectsBadConfig(t *testing.T) {
+	c := newClock()
+	bad := []struct {
+		capacity, refill float64
+		now              func() time.Time
+	}{
+		{0, 1, c.Now},
+		{-1, 1, c.Now},
+		{math.NaN(), 1, c.Now},
+		{math.Inf(1), 1, c.Now},
+		{1, 0, c.Now},
+		{1, -1, c.Now},
+		{1, math.NaN(), c.Now},
+		{1, math.Inf(1), c.Now},
+		{1, 1, nil},
+	}
+	for i, tc := range bad {
+		if _, err := ratelimit.NewBucket(tc.capacity, tc.refill, tc.now); !errors.Is(err, ratelimit.ErrInvalidConfig) {
+			t.Fatalf("case %d: err = %v, want ErrInvalidConfig", i, err)
+		}
+	}
+}
+
+func TestBucketStartsFullAndRefills(t *testing.T) {
+	c := newClock()
+	b, err := ratelimit.NewBucket(4, 2, c.Now)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if !b.Allow(4) {
+		t.Fatal("a full bucket should allow capacity tokens")
+	}
+	if b.Allow(1) {
+		t.Fatal("an empty bucket should refuse")
+	}
+	c.Advance(250 * time.Millisecond)
+	if got := b.Tokens(); got != 0.5 {
+		t.Fatalf("Tokens() = %v, want 0.5", got)
+	}
+	c.Advance(time.Hour)
+	if got := b.Tokens(); got != 4 {
+		t.Fatalf("Tokens() = %v, want capacity 4", got)
+	}
+}
+
+func TestBucketRefusesWithoutPartialConsumption(t *testing.T) {
+	c := newClock()
+	b, _ := ratelimit.NewBucket(3, 1, c.Now)
+	if !b.Allow(2) {
+		t.Fatal("Allow(2) should succeed")
+	}
+	if b.Allow(2) {
+		t.Fatal("Allow(2) with 1 token left should fail")
+	}
+	if got := b.Tokens(); got != 1 {
+		t.Fatalf("Tokens() = %v, want 1 (failed Allow must take nothing)", got)
+	}
+	if b.Allow(4) {
+		t.Fatal("n greater than capacity must be refused")
+	}
+	c.Advance(time.Hour)
+	if b.Allow(0) || b.Allow(-1) || b.Allow(math.NaN()) {
+		t.Fatal("zero, negative and NaN n must be refused")
+	}
+}
+
+func TestBucketClockGoingBackwards(t *testing.T) {
+	c := newClock()
+	b, _ := ratelimit.NewBucket(10, 1, c.Now)
+	b.Allow(10)
+	c.Advance(2 * time.Second)
+	if got := b.Tokens(); got != 2 {
+		t.Fatalf("Tokens() = %v, want 2", got)
+	}
+	c.Advance(-5 * time.Second)
+	if got := b.Tokens(); got != 2 {
+		t.Fatalf("after clock went back, Tokens() = %v, want 2", got)
+	}
+	c.Advance(6 * time.Second) // 1s past the latest time seen (+2s)
+	if got := b.Tokens(); got != 3 {
+		t.Fatalf("after clock passed latest time, Tokens() = %v, want 3", got)
+	}
+}

