+    assert!(!s.is_empty());
+    assert_eq!(s.ranges(), vec![(Bound::Closed(2), Bound::Closed(2))]);
+}
+
+#[test]
+fn open_interval_is_real_domain() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Open(2), Bound::Open(3));
+    assert!(!s.is_empty());
+    assert!(s.contains(2.5));
+    assert!(!s.contains(2.0));
+    assert!(!s.contains(3.0));
+}
+
+#[test]
+fn remove_point_splits_interval() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(1), Bound::Closed(5));
+    s.remove(Bound::Closed(2), Bound::Closed(2));
+    assert_eq!(
+        s.ranges(),
+        vec![
+            (Bound::Closed(1), Bound::Open(2)),
+            (Bound::Open(2), Bound::Closed(5)),
+        ]
+    );
+    assert!(!s.contains(2.0));
+    assert!(s.contains(1.5));
+}
+
+#[test]
+fn remove_open_window_leaves_closed_ends() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(1), Bound::Closed(5));
+    s.remove(Bound::Open(2), Bound::Open(4));
+    assert_eq!(
+        s.ranges(),
+        vec![
+            (Bound::Closed(1), Bound::Closed(2)),
+            (Bound::Closed(4), Bound::Closed(5)),
+        ]
+    );
+}
+
+#[test]
+fn remove_empty_interval_is_ignored() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(1), Bound::Closed(5));
+    s.remove(Bound::Open(3), Bound::Open(3));
+    s.remove(Bound::Closed(4), Bound::Closed(2));
+    assert_eq!(s.ranges(), vec![(Bound::Closed(1), Bound::Closed(5))]);
+}
+
+#[test]
+fn touching_intervals_merge_when_union_is_single() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(1), Bound::Open(3));
+    s.insert(Bound::Closed(3), Bound::Closed(5));
+    assert_eq!(s.ranges(), vec![(Bound::Closed(1), Bound::Closed(5))]);
+
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(1), Bound::Closed(3));
+    s.insert(Bound::Open(3), Bound::Open(5));
+    assert_eq!(s.ranges(), vec![(Bound::Closed(1), Bound::Open(5))]);
+
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Open(1), Bound::Open(3));
+    s.insert(Bound::Closed(3), Bound::Closed(3));
+    assert_eq!(s.ranges(), vec![(Bound::Open(1), Bound::Closed(3))]);
+}
+
+#[test]
+fn missing_point_or_half_open_gap_keeps_intervals_separate() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Open(1), Bound::Open(3));
+    s.insert(Bound::Open(3), Bound::Open(5));
+    assert_eq!(
+        s.ranges(),
+        vec![
+            (Bound::Open(1), Bound::Open(3)),
+            (Bound::Open(3), Bound::Open(5)),
+        ]
+    );
+
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(1), Bound::Open(3));
+    s.insert(Bound::Open(3), Bound::Closed(5));
+    assert_eq!(s.ranges().len(), 2);
+}
+
+#[test]
+fn display_canonical_form() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(7), Bound::Closed(7));
+    s.insert(Bound::Closed(1), Bound::Open(3));
+    s.insert(Bound::Open(4), Bound::Closed(5));
+    assert_eq!(s.to_string(), "{[1,3), (4,5], [7,7]}");
+
+    let mut t = IntervalSet::new();
+    t.insert(Bound::Open(-3), Bound::Closed(0));
+    assert_eq!(t.to_string(), "{(-3,0]}");
+    assert_ne!(t.to_string(), "{(-3, 0]}");
+}
+
+#[test]
+fn measure_sums_lengths_and_handles_extremes() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(1), Bound::Open(3));
+    s.insert(Bound::Closed(10), Bound::Closed(10));
+    assert_eq!(s.measure(), 2);
+
+    let mut e = IntervalSet::new();
+    e.insert(Bound::Closed(i64::MIN), Bound::Closed(i64::MAX));
+    assert_eq!(e.measure(), 18446744073709551615i128);
+    assert!(e.contains(i64::MIN as f64));
+    assert!(e.contains(i64::MAX as f64));
+    assert_ne!(e.measure(), 0);
+}
+
+#[test]
+fn complement_flips_endpoints_within_window() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(2), Bound::Open(4));
+    s.insert(Bound::Open(6), Bound::Closed(8));
+    assert_eq!(
+        s.complement(Bound::Closed(0), Bound::Closed(10)),
+        vec![
+            (Bound::Closed(0), Bound::Open(2)),
+            (Bound::Closed(4), Bound::Closed(6)),
+            (Bound::Open(8), Bound::Closed(10)),
+        ]
+    );
+    assert!(s.complement(Bound::Open(5), Bound::Open(5)).is_empty());
+    assert!(s.complement(Bound::Closed(2), Bound::Closed(2)).is_empty());
+    assert!(!s.complement(Bound::Closed(0), Bound::Closed(1)).is_empty());
+}
+
+#[test]
+fn complement_empty_when_fully_covered() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(0), Bound::Closed(10));
+    assert!(s.complement(Bound::Closed(2), Bound::Closed(3)).is_empty());
+    assert_eq!(
+        IntervalSet::new().complement(Bound::Closed(i64::MIN), Bound::Closed(i64::MAX)),
+        vec![(Bound::Closed(i64::MIN), Bound::Closed(i64::MAX))]
+    );
+}
+
+#[test]
+fn large_workload_runs_fast() {
+    let mut set = IntervalSet::new();
+    let mut seed: u64 = 0x9E37_79B9_7F4A_7C15;
+    let mut next = move || {
+        seed = seed
+            .wrapping_mul(6364136629594233893)
+            .wrapping_add(1442695040888963407);
+        seed >> 33
+    };
+    let start = Instant::now();
+    let mut pos: i64 = 1_000_000_000;
+    for i in 0..300_000u32 {
+        let step = 3000 + (next() % 667) as i64;
+        pos = (pos - step).max(0);
+        let len = (next() % 1001) as i64;
+        let lo = pos;
+        let hi = pos + len;
+        if i % 2 == 0 {
+            set.insert(Bound::Closed(lo), Bound::Closed(hi));
+        } else {
+            set.remove(Bound::Closed(lo), Bound::Closed(hi));
+        }
+        let x = (next() % 1_000_000_001) as f64;
+        let _ = set.contains(x);
+    }
+    let elapsed = start.elapsed();
+    assert!(elapsed.as_secs_f64() < 3.0, "took {:?}", elapsed);
+}

