+use romankit::{from_roman, to_roman, RomanError};
+
+#[test]
+fn to_roman_rejects_zero_and_above_3999() {
+    assert!(matches!(to_roman(0), Err(RomanError::OutOfRange)));
+    assert!(matches!(to_roman(4000), Err(RomanError::OutOfRange)));
+    assert_eq!(to_roman(3999).ok(), Some("MMMCMXCIX".to_string()));
+}
+
+#[test]
+fn to_roman_produces_canonical_numerals() {
+    assert_eq!(to_roman(1).ok(), Some("I".to_string()));
+    assert_eq!(to_roman(4).ok(), Some("IV".to_string()));
+    assert_eq!(to_roman(19).ok(), Some("XIX".to_string()));
+    assert_eq!(to_roman(1994).ok(), Some("MCMXCIV".to_string()));
+}
+
+#[test]
+fn from_roman_parses_subtractive_endings() {
+    assert!(matches!(from_roman("IV"), Ok(4)));
+    assert!(matches!(from_roman("XIX"), Ok(19)));
+    assert!(!matches!(from_roman("IV"), Ok(6)));
+    assert!(!matches!(from_roman("XIX"), Ok(21)));
+}
+
+#[test]
+fn from_roman_rejects_non_canonical_forms() {
+    assert!(matches!(from_roman("IIII"), Err(RomanError::NonCanonical)));
+    assert!(matches!(from_roman("IC"), Err(RomanError::NonCanonical)));
+    assert!(matches!(from_roman("VX"), Err(RomanError::NonCanonical)));
+    assert!(matches!(from_roman("MMMM"), Err(RomanError::NonCanonical)));
+    assert!(matches!(from_roman("IIV"), Err(RomanError::NonCanonical)));
+    assert!(matches!(from_roman("XM"), Err(RomanError::NonCanonical)));
+}
+
+#[test]
+fn from_roman_rejects_empty_string() {
+    assert!(matches!(from_roman(""), Err(RomanError::Empty)));
+}
+
+#[test]
+fn from_roman_reports_first_invalid_character() {
+    assert!(matches!(from_roman("xiv"), Err(RomanError::InvalidChar('x'))));
+    assert!(matches!(from_roman("X V"), Err(RomanError::InvalidChar(' '))));
+    assert!(matches!(from_roman("XAb"), Err(RomanError::InvalidChar('A'))));
+    assert!(matches!(from_roman("IIIIx"), Err(RomanError::InvalidChar('x'))));
+}
+
+#[test]
+fn from_roman_never_reports_out_of_range() {
+    assert!(!matches!(from_roman("MMMM"), Err(RomanError::OutOfRange)));
+    assert!(!matches!(from_roman("IIII"), Err(RomanError::OutOfRange)));
+}
+
+#[test]
+fn round_trip_is_exact_for_whole_range() {
+    for n in 1..=3999u32 {
+        let s = to_roman(n).ok().expect("in-range value must convert");
+        assert_eq!(from_roman(&s).ok(), Some(n), "round trip failed for {n}");
+    }
+}
