diff --git a/tests/loki_wall_shape.rs b/tests/loki_wall_shape.rs
new file mode 100644
index 0000000..9c5ea4e
--- /dev/null
+++ b/tests/loki_wall_shape.rs
@@ -0,0 +1,142 @@
+use shapekit::{Shape, ShapeError};
+use std::f64::consts::PI;
+
+fn close(a: f64, b: f64) -> bool {
+    (a - b).abs() < 1e-9
+}
+
+#[test]
+fn parse_kinds_are_case_insensitive_and_square_becomes_rect() {
+    assert_eq!(Shape::parse("CIRCLE", &[1.5]), Ok(Shape::Circle { r: 1.5 }));
+    assert_eq!(Shape::parse("Rect", &[2.0, 3.0]), Ok(Shape::Rect { w: 2.0, h: 3.0 }));
+    assert_eq!(Shape::parse("rectangle", &[2.0, 3.0]), Ok(Shape::Rect { w: 2.0, h: 3.0 }));
+    assert_eq!(Shape::parse("SQUARE", &[2.0]), Ok(Shape::Rect { w: 2.0, h: 2.0 }));
+    assert_eq!(
+        Shape::parse("Triangle", &[3.0, 4.0, 5.0]),
+        Ok(Shape::Triangle { a: 3.0, b: 4.0, c: 5.0 })
+    );
+    assert_eq!(
+        Shape::parse("circle", &[1.0, 2.0]),
+        Err(ShapeError::WrongParamCount { expected: 1, got: 2 })
+    );
+}
+
+#[test]
+fn parse_checks_unknown_kind_before_param_count() {
+    assert_eq!(
+        Shape::parse("Hexagon", &[]),
+        Err(ShapeError::UnknownKind("Hexagon".to_string()))
+    );
+    assert_eq!(
+        Shape::parse("hexagon", &[1.0, 2.0, 3.0]),
+        Err(ShapeError::UnknownKind("hexagon".to_string()))
+    );
+}
+
+#[test]
+fn parse_checks_param_count_before_negative_before_triangle() {
+    assert_eq!(
+        Shape::parse("circle", &[-1.0, 2.0]),
+        Err(ShapeError::WrongParamCount { expected: 1, got: 2 })
+    );
+    assert_eq!(
+        Shape::parse("triangle", &[-1.0, 1.0, 1.0]),
+        Err(ShapeError::NegativeDimension)
+    );
+    assert_eq!(
+        Shape::parse("triangle", &[1.0, 1.0, 3.0]),
+        Err(ShapeError::InvalidTriangle)
+    );
+}
+
+#[test]
+fn display_messages_match_existing_text_exactly() {
+    assert_eq!(
+        ShapeError::UnknownKind("HeXa".to_string()).to_string(),
+        "unknown shape kind: HeXa"
+    );
+    assert_eq!(
+        ShapeError::WrongParamCount { expected: 3, got: 2 }.to_string(),
+        "expected 3 params, got 2"
+    );
+    assert_eq!(
+        ShapeError::NegativeDimension.to_string(),
+        "dimensions must be non-negative"
+    );
+    assert_eq!(
+        ShapeError::InvalidTriangle.to_string(),
+        "sides do not form a triangle"
+    );
+    assert_ne!(ShapeError::NegativeDimension.to_string(), "sides do not form a triangle");
+}
+
+#[test]
+fn area_and_perimeter_compute_known_values() {
+    assert!(close(Shape::Circle { r: 1.0 }.area().unwrap(), PI));
+    assert!(close(Shape::Circle { r: 1.0 }.perimeter().unwrap(), 2.0 * PI));
+    assert!(close(Shape::Rect { w: 2.0, h: 3.0 }.area().unwrap(), 6.0));
+    assert!(close(Shape::Rect { w: 2.0, h: 3.0 }.perimeter().unwrap(), 10.0));
+    assert!(close(Shape::Triangle { a: 3.0, b: 4.0, c: 5.0 }.area().unwrap(), 6.0));
+    assert!(close(Shape::Triangle { a: 3.0, b: 4.0, c: 5.0 }.perimeter().unwrap(), 12.0));
+    assert_eq!(
+        Shape::Circle { r: -1.0 }.area(),
+        Err(ShapeError::NegativeDimension)
+    );
+}
+
+#[test]
+fn directly_built_shapes_validate_negative_before_triangle_inequality() {
+    assert_eq!(
+        Shape::Triangle { a: 1.0, b: 1.0, c: 3.0 }.area(),
+        Err(ShapeError::InvalidTriangle)
+    );
+    assert_eq!(
+        Shape::Triangle { a: 1.0, b: 1.0, c: 3.0 }.perimeter(),
+        Err(ShapeError::InvalidTriangle)
+    );
+    assert_eq!(
+        Shape::Triangle { a: -1.0, b: 1.0, c: 1.0 }.perimeter(),
+        Err(ShapeError::NegativeDimension)
+    );
+    assert_eq!(
+        Shape::Rect { w: 2.0, h: -1.0 }.perimeter(),
+        Err(ShapeError::NegativeDimension)
+    );
+}
+
+#[test]
+fn zero_dimensions_are_valid_and_degenerate_triangle_has_zero_area() {
+    assert_eq!(Shape::Rect { w: 0.0, h: 5.0 }.area(), Ok(0.0));
+    assert_eq!(Shape::Rect { w: 0.0, h: 5.0 }.perimeter(), Ok(10.0));
+    assert_eq!(Shape::Circle { r: 0.0 }.area(), Ok(0.0));
+    assert_eq!(Shape::Triangle { a: 1.0, b: 2.0, c: 3.0 }.area(), Ok(0.0));
+    assert_eq!(Shape::Triangle { a: 1.0, b: 2.0, c: 3.0 }.perimeter(), Ok(6.0));
+    assert_eq!(
+        Shape::Triangle { a: 1.0, b: 2.0, c: 3.5 }.area(),
+        Err(ShapeError::InvalidTriangle)
+    );
+}
+
+#[test]
+fn free_functions_keep_signatures_and_string_errors() {
+    let circle = shapekit::area::area("circle", &[1.0]).unwrap();
+    assert!(close(circle, PI));
+    let rect = shapekit::perimeter::perimeter("rect", &[2.0, 3.0]).unwrap();
+    assert!(close(rect, 10.0));
+    assert_eq!(
+        shapekit::area::area("hexagon", &[]),
+        Err("unknown shape kind: hexagon".to_string())
+    );
+    assert_eq!(
+        shapekit::perimeter::perimeter("triangle", &[1.0, 1.0, 3.0]),
+        Err("sides do not form a triangle".to_string())
+    );
+    assert_eq!(
+        shapekit::area::area("circle", &[-1.0]),
+        Err("dimensions must be non-negative".to_string())
+    );
+    assert_eq!(
+        shapekit::perimeter::perimeter("square", &[1.0, 2.0]),
+        Err("expected 1 params, got 2".to_string())
+    );
+}

