@@ -0,0 +1,69 @@
+use statkit::stats::{count, mean, median, percentile};
+use statkit::summary;
+
+const NAN: f64 = f64::NAN;
+
+fn assert_close(actual: Option<f64>, expected: f64) {
+    let v = actual.expect("expected Some, got None");
+    assert!((v - expected).abs() < 1e-9, "got {v}, want {expected}");
+}
+
+#[test]
+fn count_ignores_nan_values() {
+    assert_eq!(count(&[1.0, 2.0, 3.0]), 3);
+    assert_eq!(count(&[1.0, NAN, 3.0]), 2);
+    assert_eq!(count(&[NAN, NAN]), 0);
+    assert_eq!(count(&[]), 0);
+}
+
+#[test]
+fn mean_ignores_nan_and_is_none_when_empty() {
+    assert_close(mean(&[1.0, 2.0, 3.0, 4.0]), 2.5);
+    assert_close(mean(&[1.0, NAN, 3.0]), 2.0);
+    assert_eq!(mean(&[]), None);
+    assert_eq!(mean(&[NAN, NAN]), None);
+}
+
+#[test]
+fn median_is_percentile_50_and_ignores_nan() {
+    assert_close(median(&[3.0, 1.0, 4.0, 2.0]), 2.5);
+    assert_close(median(&[5.0, 1.0, 3.0]), 3.0);
+    assert_close(median(&[1.0, NAN, 3.0]), 2.0);
+    assert_eq!(median(&[]), None);
+    assert_eq!(median(&[NAN]), None);
+}
+
+#[test]
+fn percentile_interpolates_and_is_order_independent() {
+    assert_close(percentile(&[1.0, 2.0, 3.0, 4.0], 90.0), 3.7);
+    assert_close(percentile(&[4.0, 1.0, 3.0, 2.0], 90.0), 3.7);
+    assert_close(percentile(&[4.0, 1.0, 3.0, 2.0], 50.0), 2.5);
+    assert_close(percentile(&[4.0, 1.0, 3.0, 2.0], 0.0), 1.0);
+    assert_close(percentile(&[4.0, 1.0, 3.0, 2.0], 100.0), 4.0);
+    assert_close(percentile(&[4.0, 1.0, NAN, 3.0, 2.0], 100.0), 4.0);
+}
+
+#[test]
+fn percentile_rejects_bad_p_and_empty_input() {
+    assert_eq!(percentile(&[1.0, 2.0], NAN), None);
+    assert_eq!(percentile(&[1.0, 2.0], -0.5), None);
+    assert_eq!(percentile(&[1.0, 2.0], 100.5), None);
+    assert_eq!(percentile(&[NAN], 50.0), None);
+    assert_eq!(percentile(&[], 50.0), None);
+}
+
+#[test]
+fn percentile_does_not_modify_input() {
+    let v = [4.0, 1.0, 3.0, 2.0];
+    let _ = percentile(&v, 50.0);
+    assert_eq!(v, [4.0, 1.0, 3.0, 2.0]);
+}
+
+#[test]
+fn summary_report_format_and_undefined_cases() {
+    assert_eq!(summary(&[1.0, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_eq!(summary(&[4.0, 1.0, 3.0, 2.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_eq!(summary(&[1.0, NAN, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_eq!(summary(&[]), "n=0");
+    assert_eq!(summary(&[NAN, NAN]), "n=0");
+}

